<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{contactId:number;role:string;leaseToken:string;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const rows=ref<any[]>([]),page=ref(1),count=ref(0),file=ref<File|null>(null),input=ref<HTMLInputElement|null>(null),busy=ref(false),error=ref('')
let requestId=crypto.randomUUID()
function select(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;requestId=crypto.randomUUID()}
async function load(){try{const result=await props.request(`contacts/${props.contactId}/documents/?page=${page.value}`);rows.value=result.results.map((row:any)=>({...row,publicName:row.advisor_filename||'',shareReason:'',reviewed:false}));count.value=result.count}catch(e:any){error.value=e.message}}
async function upload(){if(!file.value)return;busy.value=true;error.value='';try{const data=new FormData();data.append('file',file.value);data.append('request_id',requestId);if(props.role!=='advisor')data.append('token',props.leaseToken);await props.request(`contacts/${props.contactId}/documents/`,data);file.value=null;if(input.value)input.value.value='';requestId=crypto.randomUUID();page.value=1;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function download(row:any){busy.value=true;error.value='';try{const blob=await props.request(`contacts/${props.contactId}/documents/${row.id}/download/`);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=row.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function share(row:any){busy.value=true;error.value='';try{await props.request(`contacts/${props.contactId}/documents/${row.id}/sharing/`,{revision:row.sharing_revision,enabled:!row.advisor_visible,filename:row.publicName,reason:row.shareReason,reviewed:row.reviewed});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><h3>{{role==='advisor'?'Documents accessibles':'Documents du dossier'}}</h3><p>PDF, PNG ou JPEG · 5 Mo maximum par fichier. Les documents sont internes par défaut. Chaque conseiller voit ses propres fichiers et les documents internes explicitement publiés par l’administration, sur ses dossiers autorisés. Le retrait bloque les prochains téléchargements ; les fichiers déjà téléchargés ne sont pas récupérables.</p><p v-if="error" role="alert">{{error}}</p><form @submit.prevent="upload"><input ref="input" type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="busy||(role!=='advisor'&&!leaseToken)" @change="select"><button class="primary" :disabled="busy||!file||(role!=='advisor'&&!leaseToken)">Ajouter le document</button></form><p v-if="role!=='advisor'&&!leaseToken">Prenez en charge la fiche pour ajouter un document interne.</p><article v-for="row in rows" :key="row.id"><strong>{{row.filename}}</strong><small> · {{Math.ceil(row.size/1024)}} Ko · {{row.channel==='shared'?'Partagé avec le conseiller':row.channel==='internal'?'Interne':'Conseiller'}} · {{new Date(row.created_at).toLocaleString('fr-FR')}}</small><button class="secondary" :disabled="busy" @click="download(row)">Télécharger</button><form v-if="role==='administrator'&&row.channel==='internal'" @submit.prevent="share(row)"><p>{{row.advisor_visible?'Partagé sous le nom '+row.advisor_filename:'Non partagé'}}</p><label v-if="!row.advisor_visible">Nom de fichier destiné au conseiller<input v-model="row.publicName" maxlength="180" required :disabled="busy"></label><label v-if="!row.advisor_visible"><input v-model="row.reviewed" type="checkbox" required :disabled="busy">J’ai vérifié le contenu et les métadonnées du fichier : cette version peut être transmise aux conseillers autorisés et ne révèle pas d’identité interne du setter.</label><label>Motif<input v-model="row.shareReason" maxlength="1000" required :disabled="busy"></label><button class="secondary" :disabled="busy">{{row.advisor_visible?'Retirer le partage':'Publier aux conseillers autorisés'}}</button></form></article><p v-if="!rows.length">Aucun document visible.</p><p>{{count}} document(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><button class="secondary" :disabled="busy" @click="load">Actualiser</button></section></template>
